# c++单生产者单消费者的无锁对列

来源：https://yunjinqi.top/article/491
原文发布时间：2025-04-25 14:20:53
采集时间：2026-07-19T11:51:24.720854+00:00

lf_queue.h

#pragma once #include <iostream> #include <vector> #include <atomic> #include "macros.h" namespace Common { // 无锁队列模板类，T为存储元素类型 template<typename T> class LFQueue final { public: // 构造函数，预分配num_elems个元素的空间 LFQueue(std::size_t num_elems) : store_(num_elems, T()) /* 预分配vector存储空间，每个元素初始化为T的默认值 */ { } // 获取下一个可写入的位置，返回指向元素的指针 auto getNextToWriteTo() noexcept { return &store_[next_write_index_]; } // 写入后更新写指针索引，并递增元素计数 auto updateWriteIndex() noexcept { next_write_index_ = (next_write_index_ + 1) % store_.size(); num_elements_++; } // 获取下一个可读元素的指针，如果队列为空则返回nullptr auto getNextToRead() const noexcept -> const T * { return (size() ? &store_[next_read_index_] : nullptr); } // 读取后更新读指针索引，并递减元素计数 auto updateReadIndex() noexcept { next_read_index_ = (next_read_index_ + 1) % store_.size(); // 断言确保队列非空，避免无效读取 ASSERT(num_elements_ != 0, "Read an invalid element in:" + std::to_string(pthread_self())); num_elements_--; } // 获取当前队列中元素的数量 auto size() const noexcept { return num_elements_.load(); } // 禁用默认构造、拷贝构造、移动构造和赋值操作 // 这样可以防止队列被意外复制或移动，导致资源管理错误 LFQueue() = delete; LFQueue(const LFQueue &) = delete; LFQueue(const LFQueue &&) = delete; LFQueue &operator=(const LFQueue &) = delete; LFQueue &operator=(const LFQueue &&) = delete; private: // 存储队列元素的向量，预分配固定大小 std::vector<T> store_; // 原子类型的写索引，指向下一个可写入的位置 std::atomic<size_t> next_write_index_ = {0}; // 原子类型的读索引，指向下一个可读取的位置 std::atomic<size_t> next_read_index_ = {0}; // 原子类型的元素计数器，记录当前队列中的元素数量 std::atomic<size_t> num_elements_ = {0}; }; }

例子：

#include "thread_utils.h" #include "lf_queue.h" struct MyStruct { int d_[3]; }; using namespace Common; auto consumeFunction(LFQueue<MyStruct>* lfq) { using namespace std::literals::chrono_literals; std::this_thread::sleep_for(5s); while(lfq->size()) { const auto d = lfq->getNextToRead(); lfq->updateReadIndex(); std::cout << "consumeFunction read elem:" << d->d_[0] << "," << d->d_[1] << "," << d->d_[2] << " lfq-size:" << lfq->size() << std::endl; std::this_thread::sleep_for(1s); } std::cout << "consumeFunction exiting." << std::endl; } int main(int, char **) { LFQueue<MyStruct> lfq(20); auto ct = createAndStartThread(-1, "", consumeFunction, &lfq); for(auto i = 0; i < 50; ++i) { const MyStruct d{i, i * 10, i * 100}; *(lfq.getNextToWriteTo()) = d; lfq.updateWriteIndex(); std::cout << "main constructed elem:" << d.d_[0] << "," << d.d_[1] << "," << d.d_[2] << " lfq-size:" << lfq.size() << std::endl; using namespace std::literals::chrono_literals; std::this_thread::sleep_for(1s); } ct->join(); std::cout << "main exiting." << std::endl; return 0; }

# c++构造动态内存池

来源：https://yunjinqi.top/article/490
原文发布时间：2025-04-25 14:07:46
采集时间：2026-07-19T11:51:24.721388+00:00

动态内存池代码

mem_pool.h

#pragma once #include <cstdint> #include <vector> #include <string> #include "macros.h" namespace Common { // 内存池模板类，T为存储对象的类型 template<typename T> class MemPool final { public: // 显式构造函数，预分配num_elems个对象的空间 explicit MemPool(std::size_t num_elems) : store_(num_elems, {T(), true}) /* 预分配vector存储空间，每个元素初始化为默认对象且标记为空闲 */ { // 断言：ObjectBlock的第一个成员必须是T对象 ASSERT(reinterpret_cast<const ObjectBlock *>(&(store_[0].object_)) == &(store_[0]), "T object should be first member of ObjectBlock."); } // 分配一个对象，使用可变参数构造T对象，返回T类型指针 template<typename... Args> T *allocate(Args... args) noexcept { auto obj_block = &(store_[next_free_index_]); // 断言：当前索引处的块必须为空闲 ASSERT(obj_block->is_free_, "Expected free ObjectBlock at index:" + std::to_string(next_free_index_)); T *ret = &(obj_block->object_); // 使用定位new在预分配内存上构造对象 ret = new(ret) T(args...); obj_block->is_free_ = false; // 标记为已分配 updateNextFreeIndex(); // 更新下一个空闲索引 return ret; } // 释放对象，将其标记为空闲 auto deallocate(const T *elem) noexcept { // 计算elem在store_中的索引 const auto elem_index = (reinterpret_cast<const ObjectBlock *>(elem) - &store_[0]); // 断言：元素必须属于本内存池 ASSERT(elem_index >= 0 && static_cast<size_t>(elem_index) < store_.size(), "Element being deallocated does not belong to this Memory pool."); // 断言：当前块必须是已分配状态 ASSERT(!store_[elem_index].is_free_, "Expected in-use ObjectBlock at index:" + std::to_string(elem_index)); store_[elem_index].is_free_ = true; // 标记为空闲 } // 禁用默认构造、拷贝构造、移动构造和赋值操作 MemPool() = delete; MemPool(const MemPool &) = delete; MemPool(const MemPool &&) = delete; MemPool &operator=(const MemPool &) = delete; MemPool &operator=(const MemPool &&) = delete; private: // 更新下一个空闲块的索引 auto updateNextFreeIndex() noexcept { const auto initial_free_index = next_free_index_; // 循环查找下一个空闲块 while (!store_[next_free_index_].is_free_) { ++next_free_index_; // 如果到达末尾则回到开头 if (UNLIKELY(next_free_index_ == store_.size())) { next_free_index_ = 0; } // 如果回到了起始索引，说明池已满 if (UNLIKELY(initial_free_index == next_free_index_)) { ASSERT(initial_free_index != next_free_index_, "Memory Pool out of space."); } } } // 内部结构体，包含一个对象和空闲标记 struct ObjectBlock { T object_; // 存储的对象 bool is_free_ = true; // 空闲标记，true表示可用 }; // 存储所有对象块的vector std::vector<ObjectBlock> store_; // 指向下一个空闲块的索引 size_t next_free_index_ = 0; }; }

macro.h头文件

#pragma once #include <cstring> #include <iostream> #define LIKELY(x) __builtin_expect(!!(x), 1) #define UNLIKELY(x) __builtin_expect(!!(x), 0) inline auto ASSERT(bool cond, const std::string &msg) noexcept { if (UNLIKELY(!cond)) { std::cerr << "ASSERT : " << msg << std::endl; exit(EXIT_FAILURE); } } inline auto FATAL(const std::string &msg) noexcept { std::cerr << "FATAL : " << msg << std::endl; exit(EXIT_FAILURE); }

使用例子：

#include "mem_pool.h" struct MyStruct { int d_[3]; }; int main(int, char **) { using namespace Common; MemPool<double> prim_pool(50); MemPool<MyStruct> struct_pool(50); for(auto i = 0; i < 60; ++i) { auto p_ret = prim_pool.allocate(i); auto s_ret = struct_pool.allocate(MyStruct{i, i+1, i+2}); std::cout << "prim elem:" << *p_ret << " allocated at:" << p_ret << std::endl; std::cout << "struct elem:" << s_ret->d_[0] << "," << s_ret->d_[1] << "," << s_ret->d_[2] << " allocated at:" << s_ret << std::endl; if(i % 5 == 0) { std::cout << "deallocating prim elem:" << *p_ret << " from:" << p_ret << std::endl; std::cout << "deallocating struct elem:" << s_ret->d_[0] << "," << s_ret->d_[1] << "," << s_ret->d_[2] << " from:" << s_ret << std::endl; prim_pool.deallocate(p_ret); struct_pool.deallocate(s_ret); } } return 0; }

# ubuntu上使用c++绑核进行启动多线程代码及例子

来源：https://yunjinqi.top/article/487
原文发布时间：2025-04-25 09:48:10
采集时间：2026-07-19T11:51:24.725269+00:00

这个多线程的代码算不上特别完善，还有很大的优化空间

thread_utils.h

#pragma once #include <iostream> // 标准输入输出流 #include <atomic> // 原子操作 #include <thread> // 线程支持 #include <unistd.h> // POSIX API #include <sys/syscall.h> // 系统调用 namespace Common { // 线程工具函数命名空间，提供线程相关的实用函数 /** * 设置当前线程的CPU亲和度（CPU亲和性和线程绑定） * 将当前线程固定到指定的CPU核心上运行，减少线程在不同CPU间切换带来的上下文切换开销 * 在低延迟应用中非常重要，可以减少缓存乱序和上下文切换开销 * * @param core_id 要绑定的CPU核心ID，从0开始 * @return 是否成功设置CPU亲和度 */ inline auto setThreadCore(int core_id) noexcept { cpu_set_t cpuset; // CPU集合数据结构 CPU_ZERO(&cpuset); // 初始化CPU集合，清除所有CPU CPU_SET(core_id, &cpuset); // 将指定ID的CPU添加到集合中 // 调用pthread函数设置线程的CPU亲和性 // pthread_self()获取当前线程的ID // 返回0表示成功 return (pthread_setaffinity_np(pthread_self(), sizeof(cpu_set_t), &cpuset) == 0); } /** * 创建并启动线程 * 创建一个新线程，设置其CPU亲和性，指定名称，并在其上运行给定的函数 * 使用了可变参数模板，可以接受任意类型和数量的参数 * * @param core_id 要绑定的CPU核心ID，如果为-1则不设置亲和性 * @param name 线程名称，仅用于日志记录 * @param func 要在新线程中执行的函数 * @param args 传递给函数的参数 * @return 新创建的线程对象指针 */ template<typename T, typename... A> inline auto createAndStartThread(int core_id, const std::string &name, T &&func, A &&... args) noexcept { // 创建新线程，使用lambda函数包装要执行的任务 auto t = new std::thread([&]() { // 如果指定了有效的核心ID，则设置线程的CPU亲和性 if (core_id >= 0 && !setThreadCore(core_id)) { // 如果设置失败，输出错误并终止程序 std::cerr << "Failed to set core affinity for " << name << " " << pthread_self() << " to " << core_id << std::endl; exit(EXIT_FAILURE); } // 输出设置成功的日志 std::cerr << "Set core affinity for " << name << " " << pthread_self() << " to " << core_id << std::endl; // 使用完美转发调用用户定义的函数，保留参数的值类型/引用类型 std::forward<T>(func)((std::forward<A>(args))...); }); // 等待1秒，确保线程成功启动 using namespace std::literals::chrono_literals; std::this_thread::sleep_for(1s); return t; } }

例子1：

#include "thread_utils.h" // 假设包含上述内存池和线程工具函数的头文件 #include <iostream> #include <vector> // 任务1：计算平方 void calculateSquare(int num) { for (int i = 0; i < 1000000; ++i) { std::cout << "Square of " << num << " is " << num*num << " (Core: " << sched_getcpu() << ")" << std::endl; } } // 任务2：计算立方 void calculateCube(int num) { for (int i = 0; i < 1000000; ++i) { int cube = i*i*i; } std::cout << "Cube of " << num << " is " << num*num*num << " (Core: " << sched_getcpu() << ")" << std::endl; } // 任务2：计算立方1 void calculateCube1(int num) { for (int i = 0; i < 1000000; ++i) { int cube = num*num*num; } std::cout << "Cube1 of " << num << " is " << num*num*num << " (Core: " << sched_getcpu() << ")" << std::endl; } // 任务2：计算立方2 void calculateCube2(int num) { for (int i = 0; i < 1000000; ++i) { int cube = num*num*num; } std::cout << "Cube2 of " << num << " is " << num*num*num << " (Core: " << sched_getcpu() << ")" << std::endl; } // 任务3：打印系统时间 void printSystemTime() { auto now = std::chrono::system_clock::now(); std::time_t now_time = std::chrono::system_clock::to_time_t(now); std::cout << "Current time: " << std::ctime(&now_time) << " (Core: " << sched_getcpu() << ")" << std::endl; } int main() { // 创建3个线程，分别绑定到不同核心 auto t1 = Common::createAndStartThread(2, "SquareThread", calculateSquare, 5); auto t2 = Common::createAndStartThread(2, "CubeThread", calculateCube, 7); auto t3 = Common::createAndStartThread(2, "TimeThread", printSystemTime); auto t4 = Common::createAndStartThread(2, "CubeThread1", calculateCube1, 8); auto t5 = Common::createAndStartThread(2, "CubeThread2", calculateCube2, 9); // 等待所有线程完成 t1->join(); t2->join(); t3->join(); t4->join(); t5->join(); delete t1; delete t2; delete t3; delete t4; delete t5; return 0; }

例子2

#include "thread_utils.h" auto dummyFunction(int a, int b, bool sleep) { std::cout << "dummyFunction(" << a << "," << b << ")" << std::endl; std::cout << "dummyFunction output=" << a + b << std::endl; if(sleep) { std::cout << "dummyFunction sleeping..." << std::endl; using namespace std::literals::chrono_literals; std::this_thread::sleep_for(5s); } std::cout << "dummyFunction done." << std::endl; } int main(int, char **) { using namespace Common; auto t1 = createAndStartThread(-1, "dummyFunction1", dummyFunction, 12, 21, true); auto t2 = createAndStartThread(1, "dummyFunction2", dummyFunction, 15, 51, true); std::cout << "main waiting for threads to be done." << std::endl; t1->join(); t2->join(); std::cout << "main exiting." << std::endl; return 0; }

# c++和ubuntu系统如何获取当前系统的纳秒数和时间字符串

来源：https://yunjinqi.top/article/486
原文发布时间：2025-04-24 16:30:07
采集时间：2026-07-19T11:51:24.725873+00:00

下面是具体的time_utils.h的代码，可以获取纳秒数和包含纳秒的时间字符串

#pragma once #include <string> #include <chrono> #include <ctime> namespace Common { typedef int64_t Nanos; /** * 纳秒与微秒的换算关系 */ constexpr Nanos NANOS_TO_MICROS = 1000; /** * 微秒与毫秒的换算关系 */ constexpr Nanos MICROS_TO_MILLIS = 1000; /** * 毫秒与秒的换算关系 */ constexpr Nanos MILLIS_TO_SECS = 1000; /** * 纳秒与毫秒的换算关系 */ constexpr Nanos NANOS_TO_MILLIS = NANOS_TO_MICROS * MICROS_TO_MILLIS; /** * 纳秒与秒的换算关系 */ constexpr Nanos NANOS_TO_SECS = NANOS_TO_MILLIS * MILLIS_TO_SECS; /** * 获取当前时间的纳秒数 * 返回从系统纪元（1970年1月1日）开始到现在的纳秒数 * 使用系统的高分辨率时钟，提供纳秒级分辨率 * * @return 当前时间的纳秒数值（自纪元开始） */ inline auto getCurrentNanos() noexcept { // 获取当前时间点，转换为纪元以来的时间间隔，并转换为纳秒数 return std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::system_clock::now().time_since_epoch()).count(); } /** * 获取格式化的当前时间字符串 * 将当前时间格式化为易读的字符串："YYYY-MM-DD HH:MM:SS.nanoseconds" * 例如："2023-05-15 14:30:22.123456789" * * @param time_str 用于存放格式化结果的字符串指针 * @return 格式化后的时间字符串的引用 */ inline auto& getCurrentTimeStr(std::string* time_str) { // 获取当前系统时间点 const auto now = std::chrono::system_clock::now(); const auto now_as_time = std::chrono::system_clock::to_time_t(now); // 创建tm结构体存储分解后的时间 struct tm now_tm; // 将time_t类型转换为本地时间并存入tm结构体 // localtime_r是线程安全版本 localtime_r(&now_as_time, &now_tm); // 计算纳秒部分，取模确保只有纳秒部分 const auto now_ns = std::chrono::duration_cast<std::chrono::nanoseconds> (now.time_since_epoch()).count() % 1000000000; // 使用snprintf格式化时间字符串 char buff[128]; snprintf(buff, sizeof(buff), "%04d-%02d-%02d %02d:%02d:%02d.%09ld", 1900 + now_tm.tm_year, // 年份需要加1900 now_tm.tm_mon + 1, // 月份从0开始，需要加1 now_tm.tm_mday, // 日 now_tm.tm_hour, // 小时 now_tm.tm_min, // 分钟 now_tm.tm_sec, // 秒 now_ns); // 纳秒 // 将格式化的字符串赋值给传入的字符串指针 time_str->assign(buff); // 返回结果字符串的引用 return *time_str; } }

例子：

#include <iostream> #include "time_utils.h" int main() { std::string time_str; std::cout << "Current time: " << Common::getCurrentTimeStr(&time_str) << std::endl; std::cout << "Current nanoseconds: " << Common::getCurrentNanos() << std::endl; return 0; }

# cpp蒙特卡洛计算23个人中至少有两个生日是同一天的概率？(优化代码效率版本)

来源：https://yunjinqi.top/article/398
原文发布时间：2024-10-17 12:27:07
采集时间：2026-07-19T11:51:31.713622+00:00

初始版本耗费时间：157206 ms 优化版本1耗费时间：6070.46 ms 优化版本2耗费时间：1502.49 ms 从c++编程水平上来看，chatgpt的能力还是要超过我的，优化版本2是chatgpt改进出来的。

代码优化1:

这个是晚上做梦的时候想到的，没必要去用月和日，直接用数值就好了。但是没考虑到的情况是闰年的时候2月有29天。运行耗费时间大大降低

#include <iostream> #include <chrono> #include <iostream> #include <random> #include <set> // The Birthday Problem, main() // Summary: This application simulates the birthday problem a large number of times to reveal the probability of a birthday match in a groupd of a given number of people. int main(){ const int total = 1000000; int n, matches; std::cout << "Enter the number of people in the group: " << std::flush; std::cin >> n; // 获取起始时间 auto start = std::chrono::high_resolution_clock::now(); // Initialize random number generator std::random_device rd; std::mt19937 gen(rd()); std::uniform_int_distribution<> month_dist(1, 365); if(n > 366) matches = total; else{ // Write your code here matches = 0; for (int j = 0; j < total; ++j){ std::set<int> month_day_set; for (int i=0; i<n; ++i){ int num = month_dist(gen); month_day_set.insert(num); } int num = n - month_day_set.size()?1:0; matches += num; // std::cout << "j = " << j << " matches = " << matches << std::endl; } } // 获取结束时间 auto end = std::chrono::high_resolution_clock::now(); // 计算持续时间，单位为毫秒 std::chrono::duration<double, std::milli> duration_ms = end - start; // 输出运行时间 std::cout << "The code took " << duration_ms.count() << " ms to run." << std::endl; std::cout << "The probability of a birthday match is " << (double)matches/total << "\n\n" << std::flush; return 0; }

代码优化2:

#include <iostream> #include <random> #include <vector> // Function to simulate the birthday problem bool has_duplicate_birthday(int n, std::mt19937 &gen, std::uniform_int_distribution<> &dist) { // Boolean array to mark birthdays (index from 1 to 365) std::vector<bool> birthdays(365, false); // Generate random birthdays and check for duplicates for (int i = 0; i < n; ++i) { int birthday = dist(gen); if (birthdays[birthday]) { // If this birthday has already occurred return true; // Duplicate found } birthdays[birthday] = true; // Mark this birthday as taken } return false; // No duplicate found } int main() { const int total_simulations = 1000000; int n; int matches = 0; // Ask for the number of people in the group std::cout << "Enter the number of people in the group: " << std::flush; std::cin >> n; // 获取起始时间 auto start = std::chrono::high_resolution_clock::now(); // If more than 366 people, we are guaranteed a match if (n > 366) { matches = total_simulations; } else { // Initialize random number generator and distribution (1-364 inclusive) std::random_device rd; std::mt19937 gen(rd()); std::uniform_int_distribution<> dist(0, 364); // Days from 0 to 364 // Run the simulation `total_simulations` times for (int i = 0; i < total_simulations; ++i) { if (has_duplicate_birthday(n, gen, dist)) { ++matches; } } } // 获取结束时间 auto end = std::chrono::high_resolution_clock::now(); // 计算持续时间，单位为毫秒 std::chrono::duration<double, std::milli> duration_ms = end - start; // 输出运行时间 std::cout << "The code took " << duration_ms.count() << " ms to run." << std::endl; // Output the empirical probability std::cout << "The probability of a birthday match is " << static_cast<double>(matches) / total_simulations << "\n\n" << std::flush; return 0; }

# 《quantitative finance with cpp》阅读笔记23---写二元看涨期权、二元看跌期权类，并改写看跌期权以便继承PathIndependentOption类

来源：https://yunjinqi.top/article/388
原文发布时间：2024-01-02 14:17:06
采集时间：2026-07-19T11:51:31.717920+00:00

Write DigitalCallOption and DigitalPutOption classes. Refactor PutOption so it extends PathIndependentOption.

这个题目的要求看起来并不算特别难。但是编写的时候也遇到了一些问题：c++ 错误提示：不能使用抽象类对象，这是因为基类的虚函数需要重构，但是PutOption的函数和基类不一致，这个需要改成一致才行。

参考代码

如下：

DigitalCallOption.h

